from copy import deepcopy

# Create copy and fill region with 2s
output_grid = deepcopy(input_grid)

# Replace all 0s and 2s in region 2 with 2s
# First, let me identify cells in region 2
region_2_coords = None

def find_regions(grid, exclude_value=3):
    rows, cols = len(grid), len(grid[0])
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != exclude_value and (r, c) not in visited:
                region = []

                def dfs(rr, cc):
                    if rr < 0 or rr >= rows or cc < 0 or cc >= cols:
                        return
                    if grid[rr][cc] == exclude_value or (rr, cc) in visited:
                        return
                    visited.add((rr, cc))
                    region.append((rr, cc))
                    for ddr, ddc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        dfs(ddr + rr, ddc + cc)

                dfs(r, c)
                return region
    return None

# Actually, let me use a simpler approach: flood fill from a 2, treating 3 as wall
# And fill all reachable cells with 2s

def flood_fill_and_modify(grid, new_value):
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    visited = set()

    # Find starting point (a 2)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r, c) not in visited:
                # Flood fill from here
                stack = [(r, c)]
                while stack:
                    rr, cc = stack.pop()
                    if (rr, cc) not in visited:
                        visited.add((rr, cc))
                        if result[rr][cc] == 0 or result[rr][cc] == 2:
                            result[rr][cc] = new_value
                        # Check 4 directions, not crossing 3s
                        for ddr, ddc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nrr, ncc = rr + ddr, cc + ddc
                            if 0 <= nrr < rows and 0 <= ncc < cols and grid[nrr][ncc] != 3:
                                stack.append((nrr, ncc))
                break
    return result

# Fill with 2s
output_grid = flood_fill_and_modify(input_grid, 2)
